        private static AuthoredStarDef[] ReadManifest(string data, string hero, bool needsLayout)
        {
            var rows = data.Split('\n');
            var definitions = new AuthoredStarDef[rows.Length];
            var reader = new ManifestReader(needsLayout ? HeroTreeLayout.ForTalents(HeroSigils.BaselineTreeFor(hero)) : null);
            for (int i = 0; i < rows.Length; i++)
            {
                reader.Reset(rows[i]);
                definitions[i] = (AuthoredStarDef)reader.Read();
                reader.End();
            }
            return definitions;
        }

        // A positional stream of typed constructor records; only trusted generated constants reach this reader.
        private sealed class ManifestReader
        {
            internal readonly HeroTreeLayout BaselineLayout;
            private string[] parts;
            private int at;
            internal ManifestReader(HeroTreeLayout layout) { BaselineLayout = layout; }
            internal void Reset(string row) { parts = row.Split('|'); at = 0; }
            internal void End() { if (at != parts.Length) throw new FormatException("Trailing generated star data."); }
            internal int Int() => int.Parse(parts[at++], CultureInfo.InvariantCulture);
            internal decimal Decimal() => decimal.Parse(parts[at++], CultureInfo.InvariantCulture);
            internal float Single() => float.Parse(parts[at++], CultureInfo.InvariantCulture);
            internal bool Bool() => bool.Parse(parts[at++]);
            internal string Text()
            {
                string value = parts[at++];
                if (value.IndexOf('\\') < 0) return value;
                var text = new StringBuilder(value.Length);
                for (int i = 0; i < value.Length; i++)
                {
                    char c = value[i];
                    if (c == '\\')
                    {
                        c = value[++i];
                        c = c == 'p' ? '|' : c == 'r' ? '\r' : c == 'n' ? '\n' : c;
                    }
                    text.Append(c);
                }
                return text.ToString();
            }
            internal T[] Array<T>()
            {
                int count = Int();
                if (count == 0) return System.Array.Empty<T>();
                var values = new T[count];
                for (int i = 0; i < count; i++) values[i] = (T)Read();
                return values;
            }
            internal Dictionary<string, MemoryEventKind> Triggers()
            {
                int count = Int();
                var values = new Dictionary<string, MemoryEventKind>(count, StringComparer.Ordinal);
